import {
  Button,
  Card,
  CardMedia,
  FormControl,
  Grid,
  InputLabel,
  MenuItem,
  Select,
  TextField,
  Typography,
} from "@mui/material";
import "./App.css";
import { useState } from "react";
import { useFilePicker } from "use-file-picker";
import {
  adaptifEsiklemeRequest,
  binaryRequest,
  blurringRequest,
  brightnessRequest,
  cropImageRequest,
  gaussRequest,
  grayScaleRequest,
  gurultuEklemeRequest,
  gurultuTemizlemeRequest,
  rotateRequest,
  sobelRequest,
  zoomInRequest,
} from "./requests/requests";

function App() {
  const [output, setOutput] = useState();
  const [data, setData] = useState({
    cropX: 2,
    cropY: 2,
    cropA: 200,
    cropB: 200,
    rotateValue: 90,
    brightnessFactor: 1.5,
    zoomInValue: 2,
    zoomInCenterX: 450,
    zoomInCenterY: 450,
    blur_kernel_size: 10,
    gauss_kernel_size: 10,
    gauss_sigma: 5,
    adaptifBlockSize: 15,
    adaptifCValue: 10,
    saltValue: 0.1,
    pepperValue: 0.1,
    gurultuFilterSize: 3,
    gurultuFilterType: "mean"
  });

  const handleChange = (event) => {
    setData({ ...data, gurultuFilterType: event.target.value });
  };

  const changeHandler = (e) => {
    setData({ ...data, [e.target.name]: e.target.value });
  };

  const { openFilePicker, filesContent, plainFiles, clear } = useFilePicker({
    readAs: "DataURL",
    accept: "image/*",
    multiple: false,
  });

  const runRequest = async (requestFunc, formSetupCallback) => {
    if (!plainFiles.length) return;
    const formData = new FormData();
    formData.append("file", plainFiles[0]);
    if (formSetupCallback) formSetupCallback(formData);
    const imageUrl = await requestFunc(formData);
    if (imageUrl) setOutput(imageUrl);
  };

  const temizle = () => {
    clear();
    setOutput(null);
    setData({
      cropX: 2,
      cropY: 2,
      cropA: 200,
      cropB: 200,
      rotateValue: 90,
      brightnessFactor: 1.5,
      zoomInValue: 2,
      zoomInCenterX: 450,
      zoomInCenterY: 450,
      blur_kernel_size: 10,
      gauss_kernel_size: 10,
      gauss_sigma: 5,
      adaptifBlockSize: 15,
      adaptifCValue: 10,
      saltValue: 0.1,
      pepperValue: 0.1,
      gurultuFilterSize: 3,
      gurultuFilterType: "mean"
    });
  };

  return (
    <div className="App">
      <Typography variant="h4" gutterBottom>
        Görüntü İşleme Uygulaması
      </Typography>
      <Button variant="contained" color="primary" onClick={openFilePicker}>Resim Yükle</Button>
      <Button variant="outlined" color="secondary" onClick={temizle} sx={{ ml: 2 }}>
        Temizle
      </Button>

      <Grid container spacing={2} justifyContent="center" mt={2}>
        {filesContent.length > 0 && (
          <Grid item>
            <Card>
              <CardMedia
                component="img"
                height="300"
                image={filesContent[0].content}
                alt="Yüklenen"
              />
            </Card>
          </Grid>
        )}

        {output && (
          <Grid item>
            <Card>
              <CardMedia
                component="img"
                height="300"
                image={output}
                alt="İşlenmiş"
              />
            </Card>
          </Grid>
        )}
      </Grid>

      <Grid container spacing={2} justifyContent="center" mt={3}>
        <Grid item>
          <Button onClick={() => runRequest(grayScaleRequest)}>GrayScale</Button>
        </Grid>
        <Grid item>
          <Button onClick={() => runRequest(binaryRequest)}>Binary</Button>
        </Grid>
        <Grid item>
          <Button onClick={() => runRequest(sobelRequest)}>Sobel</Button>
        </Grid>
        <Grid item>
          <Button onClick={() => runRequest(rotateRequest, (f) => f.append("x", data.rotateValue))}>Rotate</Button>
        </Grid>
        <Grid item>
          <Button onClick={() => runRequest(brightnessRequest, (f) => f.append("x", data.brightnessFactor))}>Brightness</Button>
        </Grid>
        <Grid item>
          <Button onClick={() => runRequest(blurringRequest, (f) => f.append("x", data.blur_kernel_size))}>Blurring</Button>
        </Grid>
        <Grid item>
          <Button onClick={() => runRequest(gaussRequest, (f) => {
            f.append("x", data.gauss_kernel_size);
            f.append("y", data.gauss_sigma);
          })}>Gaussian</Button>
        </Grid>
        <Grid item>
          <Button onClick={() => runRequest(adaptifEsiklemeRequest, (f) => {
            f.append("x", data.adaptifBlockSize);
            f.append("y", data.adaptifCValue);
          })}>Adaptive Threshold</Button>
        </Grid>
        <Grid item>
          <Button onClick={() => runRequest(gurultuEklemeRequest, (f) => {
            f.append("x", data.saltValue);
            f.append("y", data.pepperValue);
          })}>Salt & Pepper</Button>
        </Grid>
        <Grid item>
          <Button onClick={() => runRequest(gurultuTemizlemeRequest, (f) => {
            f.append("x", data.gurultuFilterType);
            f.append("y", data.gurultuFilterSize);
          })}>Noise Filter</Button>
        </Grid>
        <Grid item>
          <Button onClick={() => runRequest(zoomInRequest, (f) => {
            f.append("zoom_factor", data.zoomInValue);
            f.append("center_x", data.zoomInCenterX);
            f.append("center_y", data.zoomInCenterY);
          })}>Zoom</Button>
        </Grid>
        <Grid item>
          <Button onClick={() => runRequest(cropImageRequest, (f) => {
            f.append("x", data.cropX);
            f.append("y", data.cropY);
            f.append("a", data.cropA);
            f.append("b", data.cropB);
          })}>Crop</Button>
        </Grid>
      </Grid>
    </div>
  );
}

export default App;
